cases.setup_script:
/usr/bin/chmod 000 denied.bin
/usr/bin/unshare --user --map-root-user --mount /usr/bin/python3 ns_build.py spec-null.json /usr/bin/python3 ns_build.py check spec-null.json > /dev/null || { echo "CONTROL-FAILED null namespace"; exit 98; }
/usr/bin/unshare --user --map-root-user --mount /usr/bin/python3 ns_build.py spec-short8.json /usr/bin/python3 ns_build.py check spec-short8.json > /dev/null || { echo "CONTROL-FAILED short8 namespace"; exit 98; }
/usr/bin/unshare --user --map-root-user --mount /usr/bin/python3 ns_build.py spec-denied.json /usr/bin/python3 ns_build.py check spec-denied.json > /dev/null || { echo "CONTROL-FAILED denied namespace"; exit 98; }
/usr/bin/unshare --user --map-root-user --mount /usr/bin/python3 ns_build.py spec-denied.json /usr/bin/setpriv --bounding-set=-all --inh-caps=-all -- /usr/bin/python3 -I -c 'import os
try:
    os.open("/dev/urandom", 0)
    print("opened")
except PermissionError:
    print("eacces")' > "$HOME/denied.ctl"
[[ $(< "$HOME/denied.ctl") == eacces ]] || { echo "CONTROL-FAILED capability-free namespace root still opens a mode-000 file"; exit 98; }
